/* 990 entries extracted from sat.vocab.pdf. Kept compressed to keep the app lightweight. */
const PDF_WORDS_GZIP_BASE64 = '';

async function loadBundledPdfWords() {
  if (!('DecompressionStream' in window)) return null;
  const bytes = Uint8Array.from(atob(PDF_WORDS_GZIP_BASE64), character => character.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  return JSON.parse(await new Response(stream).text());
}
